SELECT close_reason, CASE WHEN opened_at >= '2026-10-10 00:15:21' THEN 'POST_V107' ELSE 'PRE_V107' END AS period, status, COUNT(*) AS n, SUM(realized_pnl < 0) AS losers, ROUND(SUM(realized_pnl),6) AS pnl_sum, ROUND(AVG(TIMESTAMPDIFF(SECOND, opened_at, closed_at)),0) AS avg_hold_s FROM paper_position WHERE status IN ('CLOSED','STOPPED') AND closed_at >= '2026-10-03 00:00:00' GROUP BY close_reason, period, status ORDER BY period, close_reason;